def save(self) -> None:
    self.path.write_text(
        json.dumps(
            {
                "updated_at": _now(),
                "enabled": self.enabled,
                "dry_run": self.dry_run,
                "sandbox": self.sandbox,
                "orders": [o.to_dict() for o in self.orders[:500]],
            },
            indent=2,
        )
    )
